// The pack's provider-breadth index. One source of truth for the snapshot of
// the 19 cloud-* providers (and their skills) that the nimbus pack carries, so
// the golden path's "escape hatch" breadth stays reachable from the pack
// itself — even after the pack is vendored into a city, away from the plugin
// sources that live alongside it in this repo.
//
// Authoritative input: each cloud-*/.claude-plugin/plugin.json plus that
// plugin's skills/*/SKILL.md frontmatter. Derived output: pack/nimbus/
// providers.json, regenerated by bin/regen-pack-providers and drift-checked by
// the 'pack-providers-in-sync' rule. This mirrors marketplace.js's
// authoritative -> derived -> regen -> drift-rule pattern; the only difference
// is the sink (a pack data file instead of marketplace.json).

import { readFileSync, readdirSync, existsSync } from "node:fs";
import { join } from "node:path";
import { loadPluginManifests } from "./marketplace.js";
import { readMarkdown } from "./skill.js";

export const PACK_PROVIDERS_REL = "pack/nimbus/providers.json";
export const PACK_MARKER_REL = "pack/pack.toml";

// The golden path the breadth sits behind. cloudflare is the one cloud-*
// provider the golden path uses directly — build=voidzero and backend=convex
// are not cloud-* providers, so they have no entry in the breadth set. The
// other 18 providers are the escape hatch for when the golden path doesn't fit.
export const GOLDEN_PATH = {
  build: "voidzero",
  backend: "convex",
  hosting: "cloudflare",
  primary_provider: "cloud-cloudflare",
};

// True when the nimbus pack is present in the repo. The regen and the drift
// rule both no-op when it is absent, so the validator/regen stay correct in a
// checkout that has dropped the pack.
export function packPresent(repoRoot) {
  return existsSync(join(repoRoot, PACK_MARKER_REL));
}

function skillsForPlugin(dir) {
  const skillsDir = join(dir, "skills");
  if (!existsSync(skillsDir)) return [];
  return readdirSync(skillsDir)
    .filter((slug) => !slug.startsWith(".") && existsSync(join(skillsDir, slug, "SKILL.md")))
    .sort()
    .map((slug) => {
      const md = readMarkdown(join(skillsDir, slug, "SKILL.md"));
      // A frontmatter parse error is reported by the skill rules; here we just
      // snapshot what we can so the index never blocks on a single bad file.
      const description = md.error ? "" : String(md.data?.description ?? "");
      return { slug, description };
    });
}

// Build the canonical provider index from the cloud-* plugin manifests + their
// skills. Deterministic: providers sorted by name, skills by slug, no
// timestamps or other nondeterminism — the serialized output must be
// byte-stable run-to-run or the drift rule is meaningless.
export function buildPackProvidersIndex(repoRoot) {
  const manifests = loadPluginManifests(repoRoot)
    .slice()
    .sort((a, b) => a.manifest.name.localeCompare(b.manifest.name));
  const providers = manifests.map(({ dir, manifest }) => {
    const skills = skillsForPlugin(dir);
    return {
      name: manifest.name,
      prefix: manifest.prefix,
      description: manifest.description,
      version: manifest.version,
      skill_count: skills.length,
      skills,
    };
  });
  return {
    schema: "nimbus.providers.v1",
    generator: "bin/regen-pack-providers",
    golden_path: GOLDEN_PATH,
    provider_count: providers.length,
    providers,
  };
}

export function serializePackProviders(index) {
  return JSON.stringify(index, null, 2) + "\n";
}

export function readPackProvidersRaw(repoRoot) {
  const path = join(repoRoot, PACK_PROVIDERS_REL);
  return existsSync(path) ? readFileSync(path, "utf8") : null;
}
